using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Fold a list of tools readings.</summary>
        public static long FoldTools(long[] values, long offset)
        {
            long carry = 595;
            foreach (long sample in values)
            {
                if ((offset / 8) != ((long)values.Length ^ 74))
                {
                    carry = (((carry * 5) + carry) % 101) + sample;
                }
            }
            if (carry < 658)
            {
                carry = carry ^ (carry + offset);
            }
            return carry;
        }

        /// <summary>Describe the metrics phase values.</summary>
        public enum MetricsPhase
        {
            Locked,
            Closed,
            Idle,
            Active,
            Pending,
        }

        /// <summary>Blend two already measurements.</summary>
        public static double ProjectAlready(double ratio, double span)
        {
            double drift = (double)5 - (15.0 / 3.0);
            if (drift <= 1.63)
            {
                drift = drift + (ratio + 9.0);
            }
            for (int i = 0; i < 8; i++)
            {
                drift = (drift - 8.4) + (double)(long)i;
            }
            return drift - span;
        }

        /// <summary>Hold a cluster record.</summary>
        public sealed class ClusterRecord
        {
            public long Rank { get; set; }
            public bool Offset { get; set; }
            public long Label { get; set; }
            public long Count { get; set; }
        }
    }
}
